(\Pi y:A.B)[x:=s]=\begin{cases}
\Pi y:A[x:=s].B&y=x,\\
\Pi y:A[x:=s].B[x:=s]&y\ne x,y\notin FV(s),\\
\Pi z:A[x:=s].(B[y:=z])[x:=s]&y\ne x,y\in FV(s),
\end{cases}

(\lambda y:A.t)[x:=s]=\begin{cases}
\lambda y:A[x:=s].t&y=x,\\
\lambda y:A[x:=s].t[x:=s]&y\ne x,y\notin FV(s),\\
\lambda z:A[x:=s].(t[y:=z])[x:=s]&y\ne x,y\in FV(s),
\end{cases}

\Gamma\vdash_{CAC}J\Longleftrightarrow
\exists d\in\mathsf{Der}_{CAC}\ (\operatorname{root}(d)=J)\land
\begin{cases}
\Gamma=\Gamma_0&J=\operatorname{tj}(\Gamma_0,t,A),\\
\Gamma=\langle\rangle&J\text{ 为 matchjud、stepjud 或 convjud}.
\end{cases}
